// th15_s7_b6  TH15 v1.00b Extra / BossCard3  "月「アポロ反射鏡」"
// Source: st07bs.ecl.txt:1736-1795 (entry), 1797-1820 (BossCard3_at dependency).
// Shared independent-invuln shell: control carries the phase; the real boss is spawned
// after OPENING_BUFFER and runs the source movement/emission timeline.
// Bullet type 16 -> TH15_STAR_R (608) via transcribe/th15/touhou-bullets.ecl.

const TH15_STAR_R: int = 608;

const TIME_LIMIT: int = 4324;     // 120 opening buffer + 4204 source frames after timerReset (frame 4)
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------------------
// Source BossCard3_at (st07bs.ecl.txt:1797-1820, dependency)
// etNew/etAim/etSprite/etCount/etAngle/etSpeed/etEx* order is preserved as one
// per-wave construction: mode3 fixed ring, 48 ways x 1 layer, speed 1.5.
// EX records:
//   0: type 2  ANIM a=1      -> birth -4*speed = -6px along each bullet angle (approved
//                               birth-animation omission keeps the retro-displacement).
//   1: type 64 BOUNCE a=1,b=13 (U/L/R; TH15 U/D/L/R 1/2/4/8) -> one bounce off the
//      screen box 384x448 (x +-192, y 0).  TH15 box >= TH target L/R/U/D 1/2/4/8, so
//      the target wall set is L|R|U = 1+2+4 = 7.
//   2: type 134217728 LASER a=0 (line), b=8, c=6, d=1 (delete parent), r=-999999
//      (keep reflected angle), s=3.5 (speed), m=32, n=96.
//   3: paired LASER_DATA type 16384: a2=18/b2=38 sounds (omitted), c2=8 effect index,
//      s2=16 width, m2=0 length limit.
// async=0 on LASER makes it wait for the active BOUNCE (bounce-then-laser).  Each
// bullet is therefore simulated by its own task: fly straight, detect the first
// U/L/R wall crossing, reflect the angle, emit the line laser there, remove the bullet.
// ---------------------------------------------------------------------------
async sub apollo_bullet() {
    var x: fx = 0fx;
    var y: fx = 0fx;
    var vx: fx = 0fx;
    var vy: fx = 0fx;
    var a: angle = 0deg;
    var lz: int = 0;
    loop {
        x = $self_x;
        y = $self_y;
        vx = $self_vx;
        vy = $self_vy;
        if vx < 0fx && x + vx <= -192fx {
            a = (32768 - ($self_angle as int)) as angle;   // reflect off left wall
            break;
        }
        if vx > 0fx && x + vx >= 192fx {
            a = (32768 - ($self_angle as int)) as angle;   // reflect off right wall
            break;
        }
        if vy < 0fx && y + vy <= 0fx {
            a = (0 - ($self_angle as int)) as angle;       // reflect off top wall
            break;
        }
        wait(1);
    }
    // EX LASER: Line, color 6, speed 3.5, source initial/target length 32/96.
    // Line judgment is 0.1L..0.9L; target approximation uses the target length L=96
    // as a moving rod of 0.8L from 0.1L.  Width w=16 (<32) -> native half-height w/4,
    // target full width 2*(w/4)=8.  active=200 bounds the offscreen flight.
    lz = laser(6, x, y, a, 96fx, 8fx, 0, 200, 0);
    if lz_alive(lz) == 1 {
        lz_start(lz, 9.6fx);
        lz_speed(lz, 3.5fx, 76.8fx);
    }
    // LASER d=1 deletes the parent bullet.  A small clear field removes this bullet
    // in the same frame's field phase (radius covers its one remaining movement step).
    clear_bullets_at(x, y, 3fx, 0);
}

// Source BossCard3_at_492 loop: wait(60) after the async first run, then
// etAngle(RANDRAD); etOn; wait(80), forever ($B=10000).
async sub apollo_shot() {
    wait(60);
    loop {
        var base: angle = (rand(65536)) as angle;
        for i in 0..48 {
            var a: angle = base + (((i * 65536) / 48) as angle);
            // ANIM birth displacement: -4*velocity = -6px along this bullet's angle.
            var bx: fx = $self_x - 6fx * cos(a);
            var by: fx = $self_y - 6fx * sin(a);
            _ = fire(TH15_STAR_R, 6, bx, by, 1.5fx, a, none, apollo_bullet);
        }
        wait(80);
    }
}

// ---------------------------------------------------------------------------
// moveLimit(0,128,240,64): outer x in [-120,120], y in [96,160]; moveRand's
// direction picker uses the inner quarter box x +-60, y 112..144.
// moveRand(30,4,2.0): fixed random direction, speed 2.0*(1-k/30) for k=1..30,
// then zero; clamped every frame by the box above.  Uses the verified helper
// shape from transcribe/th16/movement.md with this card's duration/speed/limits.
// Target phase order is ECL -> phase-5 move, so each helper call arms the next
// source movement tick; firing reads the same position sequence after waits.
// ---------------------------------------------------------------------------
sub apollo_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 30 {
        speed = (2fx * ((30 - k) as fx)) / 30fx;
    }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub apollo_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    apollo_arm_next();
}

sub apollo_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Central branch is intentionally not normalized before the vertical fix.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +-pi/2 +-0.05rad guard (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    apollo_begin_angle(a as angle);
}

sub apollo_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        apollo_arm_next();
    }
}

// ---------------------------------------------------------------------------
// Source BossCard3 entry (st07bs.ecl.txt:1736-1795).  Timed labels place the
// setup/clear block at frame 0/2/4 and the attack loop at frame 94.  Segment
// transition clears (etCancel/etClear(640), killAllAsync, enmKillAll) are
// no-ops in an isolated card and are taken over by the shell; timerReset is
// source frame 4.  setInterrupt(0,0,4200) is the phase timer (TIME_LIMIT).
// ---------------------------------------------------------------------------
async sub apollo_boss() {
    set_invuln(65535);
    // Boss() common entry frames 8-39: position (0,128), boxes 40/40 and 48/48
    // (native half-size -> target radius 20/24), body collision kept.
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // Source frames 0..4: setup and clear block, timerReset.
    apollo_wait(4);
    // Source +90: nop, async BossCard3_at, main movement loop entry.
    apollo_wait(90);
    spawn apollo_shot();
    loop {
        apollo_wait(90);
        apollo_move_rand();
        apollo_wait(40);
    }
}

// ---------------------------------------------------------------------------
// Training shell
// ---------------------------------------------------------------------------
async sub apollo_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, apollo_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, apollo_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
